insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_104_v1'
from (values
('127.762.d.7',3,'A teen group lobbies for school funding while a trade association lobbies for lower business taxes. A student sorts the two by who they represent and how they push for change. This compares and contrasts:','["interest groups and their methods of influence", "chess openings", "pasta recipes", "weather fronts"]'::jsonb,0,'Interest groups differ in goals and tactics.','original'),
('127.762.d.7',4,'Which action is a common tactic used by interest groups?','["commanding troops", "testifying at legislative hearings", "printing coins", "drawing district maps"]'::jsonb,1,'Groups testify, lobby and mobilize members.','original'),
('127.762.d.1.A',3,'A professor says that without a framework, a student of politics only collects facts and cannot explain why events happen. This discusses why:','["facts never matter", "weather predicts votes", "theories are important to the study of political science", "politics cannot be studied"]'::jsonb,2,'Theories organize and explain observations.','original'),
('127.762.d.1.A',4,'In political science, a theory is useful mainly because it:','["ends debate", "guarantees outcomes", "replaces all data", "explains and predicts patterns in political behavior"]'::jsonb,3,'Theory explains and predicts.','original'),
('127.762.d.1.B',3,'After reading Plato''s idea of philosopher-kings and Aristotle''s study of constitutions, a student summarizes what each thought makes a good state. This draws conclusions about:','["classic political theorists", "video game designers", "sports coaches", "modern pop singers"]'::jsonb,0,'Plato and Aristotle shaped political thought.','original'),
('127.762.d.1.B',4,'Aristotle classified governments by how many people rule and whether they rule for the:','["best weather", "common good or their own interest", "largest army", "oldest tradition"]'::jsonb,1,'Aristotle judged rulers'' purposes.','original'),
('127.762.d.1.C',3,'A researcher studies how voters actually behave in surveys and elections rather than how they ought to behave. This defines characteristics of contemporary theories such as:','["absolutism", "mercantilism", "behavioralism", "feudalism"]'::jsonb,2,'Behavioralism studies observable behavior.','original'),
('127.762.d.1.C',4,'Behavioralism in political science emphasizes:','["guesswork", "ancient texts only", "religious doctrine", "observation and measurement of actual political behavior"]'::jsonb,3,'Empirical focus.','original'),
('127.762.d.1.D',3,'A chart contrasts Plato''s reasoning about ideal states with modern statistical studies of voting. This compares and contrasts the:','["evolution of classic and contemporary theories", "kinds of music", "types of weather", "history of fashion"]'::jsonb,0,'Theories evolved from philosophy toward data.','original'),
('127.762.d.1.D',4,'A main difference between classic and contemporary political theory is that contemporary theory more often:','["rejects measurement", "tests ideas with evidence and data", "avoids all evidence", "relies only on tradition"]'::jsonb,1,'Modern theory is empirical.','original'),
('127.762.d.1.E',3,'A student argues that data science and social media will reshape how political scientists study voters and defends the claim with examples. This makes predictions about:','["next season''s sports", "the price of shoes", "the future of political science theory", "tomorrow''s lunch"]'::jsonb,2,'Prediction requires reasoned defense.','original'),
('127.762.d.1.E',4,'A strong defense of a prediction about political science''s future should include:','["volume", "only an opinion", "insults", "evidence and reasoning to support the claim"]'::jsonb,3,'Support claims with evidence.','original'),
('127.762.d.2.A',3,'A guide describes rule by the people, rule by religious leaders and rule by a hereditary king. This describes features of different types of government such as:','["democracy, theocracy and monarchy", "rock, paper and scissors", "breakfast, lunch and dinner", "north, south and east"]'::jsonb,0,'Governments differ by who holds power.','original'),
('127.762.d.2.A',4,'In a theocracy, government authority is based on:','["a popular vote only", "religious law and leaders", "market prices", "a trade union"]'::jsonb,1,'Religion grounds authority.','original'),
('127.762.d.2.B',3,'A student shades a world map to show where democracies, monarchies and one-party states exist today. This uses a map to label:','["rainfall levels", "airline routes", "where each form of government is practiced", "rock types"]'::jsonb,2,'Maps show governments geographically.','original'),
('127.762.d.2.B',4,'On a political map, color coding is used to:','["replace the legend", "show only rivers", "hide borders", "show categories such as types of government"]'::jsonb,3,'Colors encode categories.','original'),
('127.762.d.2.C',3,'A timeline shows tribes forming councils, then kings uniting territories, then citizens voting. This explains how each form of government:','["arose throughout history", "disappeared overnight", "never changed", "came from weather"]'::jsonb,0,'Governments arose over time.','original'),
('127.762.d.2.C',4,'Early city-states like Athens contributed to the history of government by developing:','["modern parties", "direct participation by citizens", "nuclear treaties", "the electoral college"]'::jsonb,1,'Athens pioneered direct democracy.','original'),
('127.762.d.2.D',3,'A student argues that people formed governments to gain protection and settle disputes, and supports it with reasons. This develops a logical argument for the:','["origin of music", "origin of weather", "origin of different types of government", "origin of sports"]'::jsonb,2,'Arguments explain origins.','original'),
('127.762.d.2.D',4,'One common argument for why governments formed is that people wanted:','["more disorder", "fewer laws always", "no cooperation", "order, protection and fair dispute resolution"]'::jsonb,3,'Order and security.','original'),
('127.762.d.2.E',3,'A student proposes that divine-right monarchies faded as printing spread ideas of equality and consent. This hypothesizes why some forms of government:','["became obsolete", "never existed", "stayed unchanged", "began recently"]'::jsonb,0,'Ideas and technology changed legitimacy.','original'),
('127.762.d.2.E',4,'A reasonable hypothesis for the decline of absolute monarchy is that:','["maps were redrawn", "new ideas about rights and consent spread", "people lost interest in all politics", "weather improved"]'::jsonb,1,'Enlightenment ideas weakened monarchy.','original'),
('127.762.d.3.A',3,'A reading defines movements such as feminism, Marxism and capitalism as organized sets of beliefs about society and power. This defines:','["music genres", "cooking styles", "political ideologies", "sports positions"]'::jsonb,2,'Ideologies are belief systems.','original'),
('127.762.d.3.A',4,'A political ideology is best described as:','["a court ruling", "a type of tax", "a weather pattern", "a set of beliefs about how society and government should work"]'::jsonb,3,'Ideology frames goals.','original'),
('127.762.d.3.B',3,'An analyst checks how a group sees problems, judges them, offers a remedy and organizes to act. This coordinates the elements of:','["perception, evaluation, prescription and movement in an ideology", "north, south, east and west", "spring, summer, fall and winter", "breakfast, lunch, dinner and dessert"]'::jsonb,0,'These four elements describe ideologies.','original'),
('127.762.d.3.B',4,'In the prescription element of an ideology, followers:','["blame the weather", "propose a remedy for the problems they identified", "ignore problems", "avoid action"]'::jsonb,1,'Prescription offers solutions.','original'),
('127.762.d.3.C',3,'A student predicts that rapid technological change and climate migration could inspire a new ideology. This predicts what trends could:','["stop elections forever", "end all politics", "stimulate the formation of a new ideology", "delay the seasons"]'::jsonb,2,'Social trends spark ideologies.','original'),
('127.762.d.3.C',4,'A new political ideology is most likely to arise when:','["everyone is satisfied", "nothing changes", "politics ends", "large groups feel existing ideas do not solve major problems"]'::jsonb,3,'Dissatisfaction drives new ideas.','original'),
('127.762.d.4.A',3,'A student notes how a newly independent country''s traditions, history and trust in institutions shape its politics. This makes observations about:','["the political culture of emerging nations", "cooking times", "farm tools", "weather patterns"]'::jsonb,0,'Political culture shapes politics.','original'),
('127.762.d.4.A',4,'Political culture refers to a society''s shared:','["street names", "attitudes and beliefs about politics and government", "clothing styles", "sports teams"]'::jsonb,1,'Beliefs about politics.','original'),
('127.762.d.4.B',3,'A group prepares a presentation on the history, values and civic habits of a chosen country''s politics. This researches and presents:','["a travel brochure only", "a music playlist", "the political culture of a country", "a recipe collection"]'::jsonb,2,'Political culture research.','original'),
('127.762.d.4.B',4,'A solid presentation on a country''s political culture should rely on:','["rumors", "guesses", "single anecdotes", "credible sources such as scholarly research and official data"]'::jsonb,3,'Use credible sources.','original'),
('127.762.d.5.A',3,'A council cuts local taxes while the state funds schools and the nation sets interest policy. This recognizes that government policies influence:','["the economy at the local, state and national levels", "only sports", "only art", "only weather"]'::jsonb,0,'Policy touches the economy at all levels.','original'),
('127.762.d.5.A',4,'A national government can influence the economy by changing:','["the calendar", "taxes and spending", "time zones", "the tides"]'::jsonb,1,'Fiscal policy.','original'),
('127.762.d.5.B',3,'A report lists individual income taxes, payroll taxes and corporate taxes as where federal money comes from and how each affects growth. This identifies sources of:','["traffic fines only", "school menus", "revenue for the U.S. government", "spending for the U.S. government"]'::jsonb,2,'Taxes fund government.','original'),
('127.762.d.5.B',4,'The largest single source of federal revenue is typically:','["import quotas", "parking tickets", "park fees", "individual income taxes"]'::jsonb,3,'Income taxes lead revenue.','original'),
('127.762.d.5.C',3,'A budget chart shows Social Security, defense and health programs as the biggest federal costs and their effect on debt. This identifies sources of:','["expenditures of the U.S. government", "sports funding only", "private spending", "revenue of the U.S. government"]'::jsonb,0,'Spending categories matter.','original'),
('127.762.d.5.C',4,'Which is among the largest categories of federal spending?','["parade costs", "Social Security and health programs", "office supplies only", "national park souvenirs"]'::jsonb,1,'Entitlements are large.','original'),
('127.762.d.5.D',3,'A student compares a market where firms freely compete with one where government owns the industries. This compares the role of government in:','["school systems", "weather systems", "the free enterprise system and other economic systems", "sports systems"]'::jsonb,2,'Systems differ in government''s role.','original'),
('127.762.d.5.D',4,'In a free enterprise system, government''s role is generally:','["setting every price", "owning all businesses", "banning profit", "limited, protecting property and enforcing contracts"]'::jsonb,3,'Limited government.','original'),
('127.762.d.5.E',3,'A tariff on imported steel raises prices at home and changes treaties with other countries. This explains the effects of:','["international trade on U.S. economic and political policies", "chess on school clubs", "sports on weather", "tides on beaches"]'::jsonb,0,'Trade shapes policy.','original'),
('127.762.d.5.E',4,'A tariff is best defined as a:','["tax on exports only", "tax on imported goods", "subsidy for farmers", "fee for parking"]'::jsonb,1,'Tariffs tax imports.','original'),
('127.762.d.6.A',3,'A researcher studies how family, schools, news and friends shape what people think about issues. This investigates:','["sources of ink", "sources of recipes", "sources and influences of public opinion", "sources of rivers"]'::jsonb,2,'Many forces shape opinion.','original'),
('127.762.d.6.A',4,'Which is a major source of influence on public opinion?','["sunlight", "the tide", "a map scale", "the media"]'::jsonb,3,'Media shapes views.','original'),
('127.762.d.6.B',3,'A governor delays a bill after approval ratings drop and voters flood her office with calls. This analyzes the effect of:','["public opinion on leadership", "music on voting", "leadership on weather", "sports on law"]'::jsonb,0,'Leaders respond to opinion.','original'),
('127.762.d.6.B',4,'Leaders often watch public opinion because it can affect their:','["height", "chances of reelection", "age", "hobbies"]'::jsonb,1,'Opinion influences elections.','original'),
('127.762.d.6.C',3,'A poll surveys 40 people at a mall on a weekday and claims to speak for the whole state. A student critiques this. The student critiques:','["the mall''s decor", "the weather that day", "the reliability of public opinion and how it is measured", "the poll''s font"]'::jsonb,2,'Sampling affects reliability.','original'),
('127.762.d.6.C',4,'A poll is more reliable when its sample is:','["very small", "only friends", "self-selected", "large and randomly selected"]'::jsonb,3,'Random, large samples reduce bias.','original'),
('127.762.d.6.D',3,'One poll asks ''Do you support helping struggling families?'' and another asks ''Do you want higher taxes?'' on the same program. The results differ. This compares the effects of:','["wording on poll results", "music on polls", "maps on voting", "weather on elections"]'::jsonb,0,'Question wording changes answers.','original'),
('127.762.d.6.D',4,'Loaded wording in a poll question can:','["guarantee accuracy", "push respondents toward a particular answer", "end the poll", "remove bias"]'::jsonb,1,'Wording bias.','original'),
('127.762.d.8.A',3,'A civics class traces a person from filing to run for office through the primary, general election and certification. This reviews:','["the process of baking", "the process of weather", "the process of electing public officials", "the process of painting"]'::jsonb,2,'Elections follow set steps.','original'),
('127.762.d.8.A',4,'In a primary election, voters generally:','["pick the final winner", "draw districts", "repeal laws", "choose a party''s nominee"]'::jsonb,3,'Primaries select nominees.','original'),
('127.762.d.8.B',3,'A candidate relies on a party''s volunteers, funding and brand to reach voters. This recognizes the influence of:','["political parties in elections", "bikes in elections", "fonts in elections", "tides in elections"]'::jsonb,0,'Parties support campaigns.','original'),
('127.762.d.8.B',4,'A major way parties help candidates is by:','["setting weather", "organizing volunteers and raising funds", "counting votes", "printing ballots alone"]'::jsonb,1,'Parties provide resources.','original'),
('127.762.d.8.C',3,'A strategist advises a candidate on clothing, speaking style and public persona so voters see a leader. This explores the phenomenon of:','["tax rates", "soil quality", "political image", "map reading"]'::jsonb,2,'Image influences voters.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_104_v1'
from (values
('127.762.d.8.C',4,'A candidate''s political image mainly shapes how voters:','["measure distance", "count votes", "read maps", "perceive the candidate''s character and competence"]'::jsonb,3,'Image affects perception.','original'),
('127.762.d.8.D',3,'A candidate who attacks opponents sees a backlash, while another who stays positive gains support. This describes the cause-and-effect relationship of:','["communication style in a campaign", "weather in a campaign", "pets in a campaign", "rainfall in a campaign"]'::jsonb,0,'Style affects outcomes.','original'),
('127.762.d.8.D',4,'A campaign that uses negative ads may risk:','["ending the election", "turning voters away from the sponsoring candidate", "automatic victory", "lower costs"]'::jsonb,1,'Negative ads can backfire.','original'),
('127.762.d.8.E',3,'A campaign staff weighs phone banks, TV spots, print flyers and social media by cost and reach. This compares the effectiveness of:','["school buses", "road signs", "communication methods in campaigns", "sports fields"]'::jsonb,2,'Different media reach different voters.','original'),
('127.762.d.8.E',4,'Social media can help a campaign by:','["replacing elections", "ending polls", "hiding messages", "reaching many voters quickly at low cost"]'::jsonb,3,'Low-cost reach.','original'),
('127.762.d.9.A',3,'A chart shows that governors are elected, judges may be appointed and some city managers are hired. This compares different methods of:','["filling public offices", "filling lunch trays", "filling calendars", "filling swimming pools"]'::jsonb,0,'Offices are filled in various ways.','original'),
('127.762.d.9.A',4,'Which is a method of filling a public office other than election?','["lottery of weather", "appointment", "parade", "tide"]'::jsonb,1,'Appointment is common.','original'),
('127.762.d.9.B',3,'A student explains how states choose electors and how those electors choose the president, then judges whether it works well. This analyzes and evaluates:','["the process of filing taxes", "the process of tuning a guitar", "the process of electing the president", "the process of baking bread"]'::jsonb,2,'Electoral college process.','original'),
('127.762.d.9.B',4,'The Electoral College system means a presidential candidate needs:','["a majority of states'' governors", "a Supreme Court order", "only the popular vote", "a majority of electoral votes"]'::jsonb,3,'270 electoral votes win.','original'),
('127.762.d.10.A',3,'A student explains that two major parties simplify choices and organize government, but may limit options. This discusses the functions of:','["the two-party system", "a monarchy", "the multiparty system only", "the one-party system"]'::jsonb,0,'Two-party systems structure politics.','original'),
('127.762.d.10.A',4,'One function of the two-party system is to:','["end elections", "simplify choices for voters", "remove debate", "ban candidates"]'::jsonb,1,'Parties simplify choices.','original'),
('127.762.d.10.B',3,'A Green or Libertarian candidate wins few seats but pushes the major parties to adopt new ideas. This compares the role of:','["fonts in print", "trees in forests", "third parties in the United States", "tides in the ocean"]'::jsonb,2,'Third parties influence ideas.','original'),
('127.762.d.10.B',4,'Third parties often influence U.S. politics by:','["ending primaries", "winning most elections", "abolishing parties", "raising issues that major parties later adopt"]'::jsonb,3,'Idea incubators.','original'),
('127.762.d.10.C',3,'At the city, state and national level, parties recruit candidates, register voters and get out the vote. This recognizes the role of:','["political parties in the electoral process", "clubs in sports", "bands in school", "chefs in food"]'::jsonb,0,'Parties organize elections.','original'),
('127.762.d.10.C',4,'Getting people to the polls on Election Day is often called:','["a recess", "get out the vote", "a veto", "a filibuster"]'::jsonb,1,'GOTV.','original'),
('127.762.d.10.D',3,'A teen volunteers as a poll worker, another registers voters and a third donates to a candidate. This identifies opportunities for:','["avoiding elections", "ending campaigns", "citizens to participate in the electoral process", "hiding votes"]'::jsonb,2,'Citizens can participate in many ways.','original'),
('127.762.d.10.D',4,'One way a citizen can participate in an election is by:','["skipping registration", "avoiding the polls", "ignoring candidates", "volunteering as a poll worker"]'::jsonb,3,'Poll workers help run elections.','original'),
('127.762.d.11.A',3,'A student writes that more study time raises test scores, identifies study time as the cause and test scores as the result. This examines research concepts such as:','["hypotheses and independent and dependent variables", "rhymes and rhythms", "recipes and menus", "stairs and ramps"]'::jsonb,0,'Variables and hypotheses are research basics.','original'),
('127.762.d.11.A',4,'In a hypothesis that more advertising increases votes, the independent variable is:','["the number of votes", "the amount of advertising", "the weather", "the voters'' age"]'::jsonb,1,'Independent variable is the cause.','original'),
('127.762.d.11.B',3,'A researcher uses census numbers, survey results and election returns, noting some are counts and some are percentages. This compares:','["types of shoes", "types of musical notes", "types of statistical data in political science", "types of clouds"]'::jsonb,2,'Different data types serve different analyses.','original'),
('127.762.d.11.B',4,'Survey results expressed as 62% in favor are an example of:','["a map key", "a veto", "a quorum", "a percentage"]'::jsonb,3,'Percentages summarize data.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
